@triton.jit
def _exp_strided_kernel(
    x_ptr,
    n,
    s0,
    s1,
    s2,
    s3,
    s4,
    s5,
    s6,
    s7,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    BLOCK: tl.constexpr,
    NDIM: tl.constexpr,
):
    # ``s*`` are extents and ``d*`` the matching strides, ordered innermost
    # (fastest varying logical dimension) first.
    pid = tl.program_id(0)
    idx = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK)
    mask = idx < n
    rem = idx
    off = tl.zeros((BLOCK,), dtype=tl.int64)
    if NDIM > 0:
        off += (rem % s0) * d0
        rem = rem // s0
    if NDIM > 1:
        off += (rem % s1) * d1
        rem = rem // s1
    if NDIM > 2:
        off += (rem % s2) * d2
        rem = rem // s2
    if NDIM > 3:
        off += (rem % s3) * d3
        rem = rem // s3
    if NDIM > 4:
        off += (rem % s4) * d4
        rem = rem // s4
    if NDIM > 5:
        off += (rem % s5) * d5
        rem = rem // s5
    if NDIM > 6:
        off += (rem % s6) * d6
        rem = rem // s6
    if NDIM > 7:
        off += (rem % s7) * d7
    x = tl.load(x_ptr + off, mask=mask, other=0.0)
    tl.store(x_ptr + off, tl.exp(x), mask=mask)


def _pick_block(n, itemsize):
    """Tile size in elements, chosen by bytes rather than by element count.

    A per-tile DMA/flag cost that is independent of the element size leaves
    16-bit tensors with only half the bytes of a fp32 tile per program, which is
    where their measured bandwidth deficit comes from; large 16-bit tensors
    therefore take a tile twice as wide as a fp32 tensor of the same length.
    """
    if n < (1 << 17):
        return 1024
    return 32768 // itemsize


def _is_dense_unary(t):
    """True when ``[data_ptr, data_ptr + numel)`` covers exactly this tensor.

    A dense-but-permuted tensor qualifies: the element *set* touched by a flat
    memory-order pass is exactly the tensor's own storage, so an in-place
    element-wise write is correct without logical index decomposition.  This is
    the ATen ``is_non_overlapping_and_dense`` predicate, which this build does
    not expose as a Python Tensor method.
    """
    if t.is_contiguous():
        return True
    if t.numel() <= 1:
        return True
    expected = 1
    for st, sz in sorted((d, s) for s, d in zip(t.shape, t.stride()) if s != 1):
        if st != expected:
            return False
        expected *= sz
    return True


def _collapse_dims(t):
    """Extent/stride pairs with size-1 dims dropped and mergeable dims fused.

    Two neighbouring dimensions ``(sz_a, st_a)`` and ``(sz_b, st_b)`` with
    ``st_a == st_b * sz_b`` describe one flat index ``k = a * sz_b + b`` mapping
    to ``k * st_b``, so the fused dimension keeps the *inner* stride.
    Returned innermost-first so the kernel decomposes the linear index with a
    simple cascade of ``%`` / ``//``.
    """
    pairs = [[int(sz), int(st)] for sz, st in zip(t.shape, t.stride()) if sz != 1]
    if not pairs:
        return []
    out = [pairs[0]]
    for sz, st in pairs[1:]:
        if out[-1][1] == st * sz:
            out[-1][0] *= sz
            out[-1][1] = st
        else:
            out.append([sz, st])
    return [(sz, st) for sz, st in reversed(out)]


def _launch_strided(t, n):
    dims = _collapse_dims(t)
    if len(dims) <= _MAX_DIMS:
        block = _pick_block(n, t.element_size())
        extents = [1] * _MAX_DIMS
        strides = [0] * _MAX_DIMS
        for i, (sz, st) in enumerate(dims):
            extents[i] = sz
            strides[i] = st
        _exp_strided_kernel[(triton.cdiv(n, block),)](
            t, n, *extents, *strides, BLOCK=block, NDIM=len(dims)
        )
        return
    # Deep view: peel the outermost dimension with zero-copy views.
    for i in range(t.shape[0]):
        sub = t.narrow(0, i, 1).squeeze(0)
        sub_n = sub.numel()
        if sub_n:
            _launch_strided(sub, sub_n)


def _launch_flat(t, n, block, even, i64):
    _exp_flat_kernel[(triton.cdiv(n, block),)](t, n, BLOCK=block, EVEN=even, I64=i64)


def _launch_flat_group(tensors, n):
    itemsize = tensors[0].element_size()
    block = _pick_block(n, itemsize)
    even = (n % block) == 0
    i64 = n >= (1 << 31)
    if len(tensors) == 1 or n * itemsize >= _PACK_BYTES:
        if len(tensors) > 1 and itemsize < 4:
            # 2-byte elements move half the bytes per launch, so pairing them
            # keeps the device, not 16 host launches, on the critical path.
            for k in range(0, len(tensors), 2):
                part = tensors[k : k + 2]
                if len(part) == 1:
                    _launch_flat(part[0], n, block, even, i64)
                else:
                    _exp_pair_kernel[(2, triton.cdiv(n, block))](
                        part[0], part[1], n, BLOCK=block, EVEN=even, I64=i64
                    )
            return
        for t in tensors:
            _launch_flat(t, n, block, even, i64)
        return
    counts = len(tensors)
    for k in range(0, counts, _MAX_PACK):
        part = tensors[k : k + _MAX_PACK]
        kt = len(part)
        if kt < _MAX_PACK:
            part = part + [part[0]] * (_MAX_PACK - kt)
        _exp_packed_kernel[(kt, triton.cdiv(n, block))](
            *part, n, BLOCK=block, KT=kt, EVEN=even, I64=i64
        )


def foreach_exp_(self=None):
    # Fast path: one contiguous supported tensor, the shape every timed
    # workload of a single-tensor list takes.  Skips the grouping pass so the
    # per-call host cost stays as low as possible.
    if type(self) is list and len(self) == 1:
        t = self[0]
        if (
            isinstance(t, torch.Tensor)
            and t.dtype in _SUPPORTED_DTYPES
            and t.is_contiguous()
        ):
            n = t.numel()
            if n:
                block = _pick_block(n, t.element_size())
                _exp_flat_kernel[((n + block - 1) // block,)](
                    t,
                    n,
                    BLOCK=block,
                    EVEN=(n % block) == 0,
                    I64=n >= (1 << 31),
                )
                return None
    if isinstance(self, torch.Tensor) or not isinstance(self, (list, tuple)):
        raise TypeError(
            "_foreach_exp_(): argument 'self' (position 1) must be tuple of "
            f"Tensors, not {type(self).__name__}"
        )
    if len(self) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")
    for t in self:
        if not isinstance(t, torch.Tensor):
            raise TypeError(
                "argument 'self' must be tuple of Tensors, not " f"{type(t).__name__}"
            )
        if t.dtype not in _SUPPORTED_DTYPES:
            raise RuntimeError(
                "exp_: NPU function error: call aclnnInplaceExp failed, error "
                "code is 161002. Tensor selfRef not implemented for "
                f"DT_{str(t.dtype).replace('torch.', '').upper()}, should be in "
                "dtype support list [DT_FLOAT,DT_FLOAT16,DT_BFLOAT16,"
                "DT_DOUBLE,DT_COMPLEX64,DT_COMPLEX128,]."
            )

    groups = {}
    strided = None
    for t in self:
        n = t.numel()
        if n == 0:
            continue
        if _is_dense_unary(t):
            key = (t.dtype, n)
            bucket = groups.get(key)
            if bucket is None:
                groups[key] = [t]
            else:
                bucket.append(t)
        elif strided is None:
            strided = [t]
        else:
            strided.append(t)

    for (_, n), tensors in groups.items():
        _launch_flat_group(tensors, n)
    if strided is not None:
        for t in strided:
            _launch_strided(t, t.numel())
    return None
